/* ---------------------------------------------------------------------
   owner-brands.js — the owner's own app brands, added to the library once.

   OwnerBrands.seed() adds any of these whose name is not already in the library
   (case-insensitive), then sets a localStorage flag so a brand the owner deletes
   later never comes back. They are saved with source 'owner', so they are real
   brands, not showcase/demo ones.

   Depends on onboarding.js (createFromPreset), library-store.js. Plain <script>.
   The app-icon PNGs (256px) are base64 constants at the bottom of the file.
------------------------------------------------------------------------ */

const OwnerBrands = (function () {
  'use strict';

  const FLAG = 'bd.ownerBrandsSeeded.v1';

  function svgUrl(svg) {
    return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svg)));
  }

  const NFELO_LOGO = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="256" height="256">' +
    '<rect width="256" height="256" rx="56" fill="#7db7eb"/>' +
    '<text x="128" y="148" text-anchor="middle" font-family="Helvetica Neue, Arial, sans-serif" font-weight="800" font-size="62" textLength="200" lengthAdjust="spacingAndGlyphs" fill="#1c2126">NFELO</text></svg>';

  // First listed ends up most recent.
  const BRANDS = [
    {
      name: 'Weather, Actually', tagline: 'Forecasts. 3D. Nerd mode.',
      aesthetic: 'neo-brutal-pop', bgMode: 'light',
      colors: { primary: '#bdd0e6', secondary: '#d6d6d6', accent: '#e2e5a5', neutralDark: '#353739', neutralLight: '#ffffff' },
      headingFont: 'Sora', bodyFont: 'Poppins',
      logo: () => PNG_PREFIX + WEATHER_PNG,
    },
    {
      name: 'BallKnowledge', tagline: 'Learn more about your football for all occasions',
      aesthetic: 'bento-grid', bgMode: 'light',
      colors: { primary: '#ffb43f', secondary: '#f6d094', accent: '#ffaa25', neutralDark: '#26221c', neutralLight: '#f9f8f5' },
      headingFont: 'Rubik', bodyFont: 'Poppins',
      logo: () => PNG_PREFIX + BALLKNOWLEDGE_PNG,
    },
    {
      name: 'NFELO', tagline: 'Machine Learning applied to Football',
      aesthetic: 'bento-grid', bgMode: 'light',
      colors: { primary: '#7db7eb', secondary: '#ffffff', accent: '#fbffa0', neutralDark: '#1c2126', neutralLight: '#f5f7f9' },
      headingFont: 'Figtree', bodyFont: 'Nunito Sans',
      logo: () => svgUrl(NFELO_LOGO),
    },
    {
      name: 'Some Noise', tagline: 'Build your own sleep sound',
      aesthetic: 'soft-form', bgMode: 'dark',
      colors: { primary: '#7285ed', secondary: '#da512e', accent: '#e6b833', neutralDark: '#252623', neutralLight: '#f1f0e9' },
      headingFont: 'Work Sans', bodyFont: 'Inter',   // the app uses the system font (SF Pro)
      logo: () => PNG_PREFIX + SOMENOISE_PNG,
    },
  ];

  function presetOf(b) {
    return {
      name: b.name, tagline: b.tagline, aesthetic: b.aesthetic, bgMode: b.bgMode,
      colors: b.colors, headingFont: b.headingFont, bodyFont: b.bodyFont,
      logoDataUrl: b.logo(), source: 'owner',
    };
  }

  async function seed() {
    try { if (localStorage.getItem(FLAG)) return 0; } catch (e) { return 0; }
    const have = new Set((await LibraryStore.list()).map(r => String(r.name || '').trim().toLowerCase()));
    const todo = BRANDS.filter(b => !have.has(b.name.toLowerCase()));
    const base = Date.now();
    for (let i = 0; i < todo.length; i++) {
      await Onboarding.createFromPreset(presetOf(todo[i]), { open: false, at: base - i * 1000 });
    }
    try { localStorage.setItem(FLAG, '1'); } catch (e) { /* no storage: may re-check next launch, name-match keeps it safe */ }
    return todo.length;
  }

  return { seed, names: () => BRANDS.map(b => b.name) };
})();

/* ---- app icons, 256px PNG, base64 (kept here so no file:// fetch is needed) ---- */
const PNG_PREFIX = 'data:image/png;base64,';
const WEATHER_PNG = '';
const BALLKNOWLEDGE_PNG = '';
const SOMENOISE_PNG = '';
